export type AssetKey = keyof typeof assets;

export type SummaryTile = {
  asset: AssetKey;
  /** True when the design has a dedicated summary thumbnail for this option. */
  dedicated: boolean;
  /** For reused step images: the framing to crop to with CSS (set in Prompt 13). */
  framing: string | null;
};

